81:         if (m_clientPublicKey.isEmpty()) {
82:             return getErrorReply(action, ERROR_KEEPASS_CLIENT_PUBLIC_KEY_NOT_RECEIVED);
83:         } else if (!browserService()->openDatabase(triggerUnlock)) {
84:             return getErrorReply(action, ERROR_KEEPASS_DATABASE_NOT_OPENED);
